<?php
declare(strict_types=1); namespace App\Controller; use App\Entity\Application; use App\Entity\Candidate; use App\Entity\Job; use App\Entity\User; use App\Service\ApplicationManager; use Doctrine\ORM\EntityManagerInterface; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\Request; use Symfony\Component\HttpFoundation\Response; use Symfony\Component\Routing\Attribute\Route; use Symfony\Component\Security\Http\Attribute\IsGranted;
#[Route('/candidate'),IsGranted('ROLE_CANDIDATE')] final class CandidateController extends AbstractController { private function candidate(EntityManagerInterface $em):Candidate{$u=$this->getUser();if(!$u instanceof User)throw $this->createAccessDeniedException();$c=$em->getRepository(Candidate::class)->findOneBy(['user'=>$u]);if(!$c)throw $this->createNotFoundException('Candidate profile not found.');return $c;} #[Route('/applications',name:'candidate_applications')] public function applications(EntityManagerInterface $em):Response{return $this->render('candidate/applications.html.twig',['applications'=>$em->getRepository(Application::class)->findBy(['candidate'=>$this->candidate($em)],['submittedAt'=>'DESC'])]);} #[Route('/jobs/{id}/apply',name:'candidate_apply',methods:['GET','POST'])] public function apply(Job $job,Request $r,EntityManagerInterface $em,ApplicationManager $manager):Response{if($r->isMethod('POST')){if(!$this->isCsrfTokenValid('apply'.$job->getId(),(string)$r->request->get('_token')))throw $this->createAccessDeniedException();try{$manager->apply($this->candidate($em),$job,$r->request->get('coverLetter'));$this->addFlash('success','Application submitted.');return $this->redirectToRoute('candidate_applications');}catch(\DomainException $e){$this->addFlash('danger',$e->getMessage());}}return $this->render('candidate/apply.html.twig',['job'=>$job]);} }
